     1→import type { EventTimelineItem } from "@unomed/react-native-matrix-sdk";
     2→import { useAtomValue } from "jotai";
     3→import { getEventId } from "modules/matrix-client/utils";
     4→import { TimelineAtoms } from "../jotai/atoms";
     5→
     6→/**
     7→ * Hook to check if a message is pinned
     8→ * @param event - The event timeline item to check
     9→ * @returns boolean indicating if the message is pinned
    10→ */
    11→export const useIsPinned = (event: EventTimelineItem): boolean => {
    12→  const pinnedEventIds = useAtomValue(TimelineAtoms.pinnedEventIds);
    13→  const eventId = getEventId(event);
    14→
    15→  if (!eventId) return false;
    16→
    17→  return pinnedEventIds.includes(eventId);
    18→};
