     1→import type { DocumentPickerResponse } from "@react-native-documents/picker";
     2→import {
     3→  type AudioMessageContent,
     4→  EditedContent,
     5→  type EventTimelineItem,
     6→  type FileMessageContent,
     7→  type ImageMessageContent,
     8→  MessageType_Tags,
     9→  MsgLikeKind_Tags,
    10→  TimelineItemContent_Tags,
    11→  type UploadParameters,
    12→  UploadSource,
    13→  type VideoMessageContent,
    14→  messageEventContentFromMarkdown,
    15→} from "@unomed/react-native-matrix-sdk";
    16→import { MatrixCore } from "../../matrix-client/services/MatrixCore";
    17→import { getEventId } from "../../matrix-client/utils";
    18→
    19→export type ForwardMessageType = "text" | "image" | "video" | "audio" | "file";
    20→
    21→export class TimelineService {
    22→  public static sendMessage = async (roomId: string, message: string) => {
    23→    const room = MatrixCore.getRoom(roomId);
    24→    const timeline = await room.timeline();
    25→    if (!timeline) throw new Error("Timeline not found");
    26→    const messageContent = messageEventContentFromMarkdown(message);
    27→    await timeline.send(messageContent);
    28→  };
    29→
    30→  public static replyToMessage = async (
    31→    roomId: string,
    32→    message: string,
    33→    eventId: string,
    34→  ) => {
    35→    const room = MatrixCore.getRoom(roomId);
    36→    const timeline = await room.timeline();
    37→    if (!timeline) throw new Error("Timeline not found");
    38→    const messageContent = messageEventContentFromMarkdown(message);
    39→    await timeline.sendReply(messageContent, eventId);
    40→  };
    41→
    42→  public static editMessage = async (
    43→    roomId: string,
    44→    event: EventTimelineItem,
    45→    message: string,
    46→  ) => {
    47→    const room = MatrixCore.getRoom(roomId);
    48→    const timeline = await room.timeline();
    49→    if (!timeline) throw new Error("Timeline not found");
    50→
    51→    if (!event.eventOrTransactionId) {
    52→      throw new Error("Event is missing event or transaction id");
    53→    }
    54→
    55→    const messageContent = messageEventContentFromMarkdown(message);
    56→    const editedContent = EditedContent.RoomMessage.new({ content: messageContent });
    57→    await timeline.edit(event.eventOrTransactionId, editedContent);
    58→  };
    59→
    60→  public static reportMessage = async (
    61→    roomId: string,
    62→    event: EventTimelineItem,
    63→    reason: string,
    64→  ) => {
    65→    const room = MatrixCore.getRoom(roomId);
    66→    const eventId = getEventId(event);
    67→    if (!eventId) throw new Error("Event is missing event id");
    68→    await room.reportContent(eventId, undefined, reason);
    69→  };
    70→
    71→  public static deleteMessage = async (
    72→    roomId: string,
    73→    event: EventTimelineItem,
    74→  ) => {
    75→    const room = MatrixCore.getRoom(roomId);
    76→    const eventId = getEventId(event);
    77→    if (!eventId) throw new Error("Event is missing event id");
    78→    await room.redact(eventId, undefined);
    79→  };
    80→
    81→  public static forwardMessage = async (
    82→    roomId: string,
    83→    event: EventTimelineItem,
    84→    messageType: ForwardMessageType,
    85→  ) => {
    86→    const client = MatrixCore.getClient();
    87→    const room = MatrixCore.getRoom(roomId);
    88→    const timeline = await room.timeline();
    89→    if (!timeline) throw new Error("Timeline not found");
    90→
    91→    if (messageType === "text") {
    92→      const textContent = TimelineService.getTextContent(event);
    93→      if (!textContent) throw new Error("Text content not found");
    94→      await timeline.send(messageEventContentFromMarkdown(textContent));
    95→      return;
    96→    }
    97→
    98→    if (messageType === "image") {
    99→      const imageContent = TimelineService.getImageContent(event);
