    31→export const MessageContentBottomSheet: React.FC<Props> = ({ roomId }) => {
    32→  const ref = useRef<BottomSheetModal>(null);
    33→  const fadeIn = useRef(
    34→    animateSequence(
    35→      { opacity: [0, 1] },
    36→      {
    37→        duration: 200,
    38→      },
    39→    ),
