    48→  }, [payload]);
    49→  const displayName = useMemo(() => {
    50→    return payload?.event.senderProfile.tag === ProfileDetails_Tags.Ready
    51→      ? payload?.event.senderProfile.inner.displayName
    52→      : undefined;
    53→  }, [payload]);
    54→  const isOwn = useMemo(() => payload?.event.isOwn, [payload]);
    55→  const isTextMessage = useMemo(
    56→    () => payload?.messageType === "text",
    57→    [payload],
    58→  );
    59→  const canEdit = useMemo(() => isOwn && isTextMessage, [isOwn, isTextMessage]);
    60→  const [isPinLoading, setIsPinLoading] = useState(false);
    61→  const pinnedEventIds = useAtomValue(TimelineAtoms.pinnedEventIds);
    62→  const eventId = useMemo(() => {
    63→    if (!payload) return null;
    64→    return getEventId(payload.event);
    65→  }, [payload]);
    66→  const isPinned = useMemo(() => {
    67→    if (!eventId) return false;
    68→    return pinnedEventIds.includes(eventId);
    69→  }, [eventId, pinnedEventIds]);
    70→  /** If the user is at least a moderator, they can pin messages */
    71→  const isModeratorAtLeast = useMemo(() => {
    72→    if (!userPowerLevel) return false;
    73→    return userPowerLevel >= 50;
    74→  }, [userPowerLevel]);
    75→  const setReplyPayload = useSetAtom(TimelineAtoms.replyPayload);
    76→  const setEditPayload = useSetAtom(TimelineAtoms.editPayload);
    77→  const setForwardPayload = useSetAtom(TimelineAtoms.forwardPayload);
    78→  const setReportPayload = useSetAtom(TimelineAtoms.reportPayload);
    79→  const setPinnedEventIds = useSetAtom(TimelineAtoms.pinnedEventIds);
    80→
    81→  const handleBottomSheetClose = useCallback(() => {
    82→    fadeIn.reverse(() => {
    83→      setPayload(null);
    84→    });
    85→  }, [fadeIn, setPayload]);
    86→
    87→  const handleReply = useCallback(() => {
    88→    if (!payload) return;
