    97→        const kind = event.content.inner.content.kind;
    98→        if (kind?.tag === MsgLikeKind_Tags.Message) {
    99→          const msgType = kind.inner.content.msgType;
   100→          if (msgType?.tag === MessageType_Tags.Image) {
   101→            const imageContent = msgType.inner.content;
   102→            mediaSource = {
   103→              source: imageContent.source,
   104→              mimetype: imageContent.info?.mimetype || "image/jpeg",
   105→            };
   106→          } else if (msgType?.tag === MessageType_Tags.Video) {
   107→            const videoContent = msgType.inner.content;
   108→            mediaSource = {
   109→              source: videoContent.source,
   110→              mimetype: videoContent.info?.mimetype || "video/mp4",
   111→            };
   112→          }
   113→        }
   114→      }
   115→    }
   116→
   117→    setEditPayload(null);
   118→    setReplyPayload({
   119→      eventId,
   120→      senderName: displayName ?? payload.event.sender,
   121→      content: payload.content,
   122→      mediaSource,
   123→    });
   124→
   125→    ref.current?.dismiss();
   126→  }, [payload, displayName, setEditPayload, setReplyPayload]);
   127→
   128→  const handleEdit = useCallback(() => {
   129→    if (!payload?.event.isOwn || payload?.messageType !== "text") return;
   130→
   131→    setReplyPayload(null);
   132→    setEditPayload({
   133→      event: payload.event,
   134→      senderName: displayName ?? payload.event.sender,
