    17→import { TimelineAtoms } from "modules/timeline/jotai";
    18→import { TimelineService } from "modules/timeline/service/TimelineService";
    19→import { type FC, useCallback, useEffect, useMemo, useState } from "react";
    20→import { Dimensions, Image, StyleSheet } from "react-native";
    21→import { MessageTimestamp, PinIndicator, SeenBy } from "shared/components";
