    24→import { MessageSender } from "../message-sender";
    25→import { ReplyPayload } from "../reply-paylaod";
    26→
    27→interface Props {
    28→  event: EventTimelineItem;
    29→  isPreviousSameSender: boolean;
    30→  onMemberPress?: (member: MemberDetailsPayload) => void;
    31→}
    32→
    33→const { width } = Dimensions.get("window");
    34→
    35→export const TextMessage: FC<Props> = ({
    36→  event,
    37→  isPreviousSameSender,
    38→  onMemberPress,
    39→}) => {
    40→  const [messageWidth, setMessageWidth] = useState(40);
    41→  const isUser = event.isOwn;
    42→  const sender = event.senderProfile;
    43→  const senderId = event.sender;
    44→  const [seenBy, setSeenBy] = useState<UserProfile[]>([]);
    45→  const content = getEventTextContent(event);
    46→  const maxWidth = width - 60; // Minus horizontal paddings and 20 extra to prevent to be too wide
    47→  const setScrollToEventId = useSetAtom(TimelineAtoms.scrollToEventId);
    48→
    49→  const replyPayload = useMemo(() => {
    50→    if (event.content.tag !== TimelineItemContent_Tags.MsgLike) return null;
    51→
    52→    const inReplyTo = event.content.inner.content.inReplyTo;
    53→
    54→    if (!inReplyTo) return null;
    55→
    56→    const eventDetails = inReplyTo.event();
    57→    if (eventDetails.tag !== EmbeddedEventDetails_Tags.Ready) return null;
    58→
    59→    const senderName =
    60→      eventDetails.inner.senderProfile.tag === ProfileDetails_Tags.Ready
    61→        ? (eventDetails.inner.senderProfile.inner.displayName ??
    62→          eventDetails.inner.sender)
    63→        : eventDetails.inner.sender;
    64→
    65→    let mediaSource: { source: MediaSourceInterface; mimetype: string } | null =
    66→      null;
    67→    const replyContent = eventDetails.inner.content;
    68→
    69→    if (replyContent.tag === TimelineItemContent_Tags.MsgLike) {
    70→      const kind = replyContent.inner.content.kind;
    71→      if (kind?.tag === MsgLikeKind_Tags.Message) {
    72→        const msgType = kind.inner.content.msgType;
    73→        if (msgType?.tag === MessageType_Tags.Image) {
    74→          mediaSource = {
    75→            source: msgType.inner.content.source,
    76→            mimetype: msgType.inner.content.info?.mimetype || "image/jpeg",
    77→          };
    78→        } else if (msgType?.tag === MessageType_Tags.Video) {
    79→          mediaSource = {
    80→            source: msgType.inner.content.source,
    81→            mimetype: msgType.inner.content.info?.mimetype || "video/mp4",
    82→          };
    83→        }
    84→      }
    85→    }
    86→
    87→    return {
    88→      eventId: inReplyTo.eventId(),
    89→      senderName,
    90→      content: getMessageTextContent(eventDetails.inner.content),
    91→      mediaSource,
    92→    };
    93→  }, [event]);
    94→
    95→  const handleReplyPress = useCallback(() => {
    96→    if (replyPayload) setScrollToEventId(replyPayload.eventId);
    97→  }, [replyPayload, setScrollToEventId]);
    98→
    99→  useEffect(() => {
   100→    TimelineService.getReadReceipts(event)
   101→      .then(setSeenBy)
   102→      .catch((error) => {
   103→        console.error("Failed to get read receipt users:", error);
   104→        setSeenBy([]);
   105→      });
   106→  }, [event]);
   107→
   108→  return (
   109→    <Block
   110→      align={isUser ? "flex-end" : "flex-start"}
   111→      margins={{ marginTop: isPreviousSameSender ? 6 : 16 }}
   112→    >
   113→      <MessageSender
   114→        sender={sender}
   115→        senderId={senderId}
   116→        isUser={isUser}
   117→        isPreviousSameSender={isPreviousSameSender}
   118→        onMemberPress={onMemberPress}
   119→      />
   120→      <MessageLongPressWrapper event={event} content={content}>
   121→        <Block flexDirection={isUser ? "row-reverse" : "row"}>
   122→          <Block
   123→            paddings={12}
   124→            background={isUser ? Colors.primary : Colors.message}
   125→            border={{ borderRadius: 24 }}
   126→            align="stretch"
   127→            gap={12}
   128→            onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
   129→            maxWidth={maxWidth}
   130→          >
   131→            <ReplyPayload
   132→              replyPayload={replyPayload}
   133→              onPress={handleReplyPress}
   134→            />
   135→            <Block
   136→              justify="space-between"
   137→              align="center"
   138→              flex={{ flexWrap: "wrap" }}
   139→              flexDirection={isUser ? "row-reverse" : "row"}
   140→              gap={{
   141→                row: 4,
   142→                col: 16,
   143→              }}
   144→              // Some short strings (e.g., "aa", "ai") wrap unexpectedly, while others ("dd", "a") do not.
   145→              // Add this value to prevent unwanted wrapping for short text.
   146→              minWidth={72}
   147→            >
   148→              <Text size={TextSize.small} color="white">
   149→                {content}
   150→              </Text>
   151→              <MessageTimestamp event={event} isUser={isUser} />
   152→            </Block>
   153→            {isPreviousSameSender && (
   154→              <Block
   155→                absolute
   156→                offsets={
   157→                  isUser
   158→                    ? {
   159→                        right: 6,
   160→                        bottom: 2,
   161→                      }
   162→                    : {
   163→                        left: 6,
   164→                        bottom: 2,
   165→                      }
   166→                }
   167→              >
   168→                <Image
   169→                  source={
   170→                    isUser
   171→                      ? require("assets/icons/polygon.png")
   172→                      : require("assets/icons/guest-polygon.png")
   173→                  }
   174→                  width={7}
   175→                  height={6}
   176→                  style={styles.polygon}
   177→                />
   178→              </Block>
   179→            )}
   180→          </Block>
   181→          <PinIndicator event={event} />
   182→        </Block>
   183→      </MessageLongPressWrapper>
   184→      <SeenBy seenBy={seenBy} messageWidth={messageWidth} />
   185→    </Block>
   186→  );
   187→};
   188→
   189→const styles = StyleSheet.create({
   190→  polygon: {
   191→    width: 7,
   192→    height: 6,
   193→  },
   194→});
