    13→import { fetchMedia, getEventTextContent } from "modules/matrix-client/utils";
    14→import { TimelineAtoms } from "modules/timeline/jotai";
    15→import { TimelineService } from "modules/timeline/service/TimelineService";
    16→import { type FC, useCallback, useEffect, useMemo, useState } from "react";
    17→import { Image } from "react-native";
    18→import {
    19→  Loading,
    20→  MessageTimestamp,
    21→  PinIndicator,
    22→  SeenBy,
    23→} from "shared/components";
    24→import { Colors, TextSize } from "shared/styles";
    25→import {
    26→  cacheImageWithKey,
    27→  getCachedImagePathByURL,
    28→  isCached,
    29→} from "shared/utils/image-caching";
    30→import { MessageLongPressWrapper } from "../message-long-press-wrapper";
    31→import { MessageSender } from "../message-sender";
    32→
    33→interface Props {
    34→  event: EventTimelineItem;
    35→  isPreviousSameSender: boolean;
    36→  onMemberPress?: (member: MemberDetailsPayload) => void;
    37→}
    38→
    39→const MAX_DIMENSION = 300;
    40→
    41→const getImageContent = (
    42→  event: EventTimelineItem,
    43→): ImageMessageContent | null => {
    44→  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    45→    const kind = event.content.inner.content.kind;
    46→    if (kind?.tag === MsgLikeKind_Tags.Message) {
    47→      const msgType = kind.inner.content.msgType;
    48→      if (msgType?.tag === MessageType_Tags.Image) {
    49→        return msgType.inner.content;
    50→      }
    51→    }
    52→  }
    53→  return null;
    54→};
    55→
    56→export const ImageMessage: FC<Props> = ({
    57→  event,
    58→  isPreviousSameSender,
    59→  onMemberPress,
    60→}) => {
    61→  const content = getImageContent(event);
    62→  const [messageWidth, setMessageWidth] = useState(40);
    63→  const originalWidth = Number(content?.info?.thumbnailInfo?.width) || 0;
    64→  const originalHeight = Number(content?.info?.thumbnailInfo?.height) || 0;
    65→  const scaleRatio = Math.min(
    66→    MAX_DIMENSION / originalWidth,
    67→    MAX_DIMENSION / originalHeight,
    68→    1,
    69→  );
    70→  const targetWidth = Math.round(originalWidth * scaleRatio);
    71→  const targetHeight = Math.round(originalHeight * scaleRatio);
    72→  const [uri, setUri] = useState<string | null>(null);
    73→  const [isLoading, setIsLoading] = useState(true);
    74→  const isUser = event.isOwn;
    75→  const sender = event.senderProfile;
    76→  const senderId = event.sender;
    77→  const caption = content?.caption;
    78→  const [seenBy, setSeenBy] = useState<UserProfile[]>([]);
    79→  const background = useMemo(() => {
    80→    if (!caption) return "transparent";
    81→    return isUser ? Colors.primary : Colors.message;
    82→  }, [caption, isUser]);
    83→  const setImageViewerUri = useSetAtom(TimelineAtoms.imageViewerUri);
    84→
    85→  const openImageViewer = useCallback(() => {
    86→    if (!uri || isLoading) return;
    87→    setImageViewerUri(uri);
    88→  }, [uri, isLoading, setImageViewerUri]);
    89→
    90→  useEffect(() => {
    91→    TimelineService.getReadReceipts(event)
    92→      .then((users) => {
    93→        setSeenBy(users);
    94→      })
    95→      .catch((error) => {
    96→        console.error("Failed to get read receipt users:", error);
    97→        setSeenBy([]);
    98→      });
    99→  }, [event]);
   100→
   101→  useEffect(() => {
   102→    if (!content) return;
   103→    const mxcUrl = content.source.url();
   104→    if (!mxcUrl) return;
   105→
   106→    const load = async () => {
   107→      try {
   108→        if (await isCached(mxcUrl)) {
   109→          setUri(getCachedImagePathByURL(mxcUrl));
   110→          return;
   111→        }
   112→
   113→        const httpUrl = await fetchMedia({
   114→          serverUrl:
   115→            MatrixCore.instance?.session().homeserverUrl || MatrixBaseURL,
   116→          mediaSource: content.source,
   117→          mimeType: content.info?.mimetype || "image/jpeg",
   118→        });
   119→
   120→        if (!httpUrl) return;
   121→
   122→        await cacheImageWithKey(mxcUrl, httpUrl);
   123→        setUri(getCachedImagePathByURL(mxcUrl));
   124→      } catch (error) {
   125→        console.error(error);
   126→      } finally {
   127→        setIsLoading(false);
   128→      }
   129→    };
   130→
   131→    load();
   132→  }, [content]);
   133→
   134→  if (!content) return null;
   135→
   136→  return (
   137→    <Block
   138→      align={isUser ? "flex-end" : "flex-start"}
   139→      margins={{ marginTop: isPreviousSameSender ? 6 : 16 }}
   140→    >
   141→      <MessageSender
   142→        sender={sender}
   143→        senderId={senderId}
   144→        isUser={isUser}
   145→        isPreviousSameSender={isPreviousSameSender}
   146→        onMemberPress={onMemberPress}
   147→      />
   148→      <Block flexDirection={isUser ? "row-reverse" : "row"}>
   149→        <Block
   150→          background={background}
   151→          border={{ borderRadius: 12 }}
   152→          paddings={caption ? [4, 4, 12] : 0}
   153→          gap={8}
   154→        >
   155→          <Block
   156→            background="transparent"
   157→            border={{
   158→              borderRadius: 12,
   159→            }}
   160→            align="center"
   161→            overflow="hidden"
   162→            width={targetWidth}
   163→            height={targetHeight}
   164→            onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
   165→          >
   166→            {isLoading ? (
   167→              <Block
   168→                width="100%"
   169→                height="100%"
   170→                background={Colors.white20}
   171→                align="center"
   172→                justify="center"
   173→              >
   174→                <Loading isFullScreen={false} />
   175→              </Block>
   176→            ) : uri ? (
   177→              <MessageLongPressWrapper
   178→                event={event}
   179→                content={getEventTextContent(event)}
   180→                onFinalize={openImageViewer}
   181→              >
   182→                <Image
   183→                  source={{ uri }}
   184→                  width={targetWidth}
   185→                  height={targetHeight}
   186→                  resizeMode="contain"
   187→                />
   188→              </MessageLongPressWrapper>
   189→            ) : null}
   190→          </Block>
   191→
   192→          {caption ? (
   193→            <Block
   194→              maxWidth={targetWidth}
   195→              justify="space-between"
   196→              flexDirection={isUser ? "row-reverse" : "row"}
   197→              gap={{
   198→                row: 4,
   199→                col: 16,
   200→              }}

